"""FrameBoost 极帧加速 — 内嵌应用图标（自动生成，请勿手改）."""

from __future__ import annotations

import base64

from PySide6.QtGui import QIcon, QPixmap

_ICON_PNG_B64 = ""


def load_icon() -> QIcon:
    """加载内嵌图标为 QIcon."""
    data = base64.b64decode(_ICON_PNG_B64)
    pm = QPixmap()
    pm.loadFromData(data, "PNG")
    return QIcon(pm)
